#!/usr/bin/env bash
set -Eeuo pipefail
trap 'echo "Installation failed at line $LINENO. PataPesa and official Yakit services were not changed." >&2' ERR
[ "$(id -u)" -eq 0 ] || { echo 'Run with sudo bash'; exit 1; }
[ -f /var/lib/yakit-full/password ] && [ -f /var/lib/yakit-full/secret ] || { echo 'Existing full Yakit password/secret missing. Stop.'; exit 1; }
id yakview >/dev/null 2>&1 || { echo 'Existing yakview service user missing. Stop.'; exit 1; }
PY=/opt/yakit-full/venv/bin/python
[ -x "$PY" ] && "$PY" -c 'import aiohttp' || { echo 'Desktop Python aiohttp environment missing. Stop.'; exit 1; }
if ss -lntp | grep -q '127.0.0.1:6090 ' && ! systemctl is-active --quiet yakit-mobile-native 2>/dev/null; then
  echo 'Port 6090 is occupied by an unrelated process. Stop.'; exit 1
fi
printf '%s\n' '[1/4] Installing isolated mobile code and data...'
tmp=$(mktemp -d)
trap 'rm -rf "$tmp"' EXIT
base64 -d > "$tmp/app.tar.gz" <<'__YAKIT_MOBILE_ARCHIVE__'

__YAKIT_MOBILE_ARCHIVE__
mkdir -p "$tmp/unpack"
tar -xzf "$tmp/app.tar.gz" -C "$tmp/unpack" --no-same-owner
install -d -m 755 /opt/yakit-mobile-native
install -d -o yakview -g yakview -m 700 /var/lib/yakit-mobile
if [ -f /opt/yakit-mobile-native/app.py ]; then
  cp -a /opt/yakit-mobile-native/app.py /opt/yakit-mobile-native/app.py.pre-mobile-update
fi
cp -f "$tmp/unpack/app.py" /opt/yakit-mobile-native/app.py
install -d -m 755 /opt/yakit-mobile-native/static
cp -f "$tmp/unpack/static/"* /opt/yakit-mobile-native/static/
cp -f "$tmp/unpack/README.md" /opt/yakit-mobile-native/README.md
chmod 644 /opt/yakit-mobile-native/app.py /opt/yakit-mobile-native/static/* /opt/yakit-mobile-native/README.md
"$PY" -m py_compile /opt/yakit-mobile-native/app.py
printf '%s\n' '[2/4] Registering localhost-only systemd service...'
cat > /etc/systemd/system/yakit-mobile-native.service <<'SERVICE'
[Unit]
Description=Mobile-first authorized security workbench for Yakit
After=network-online.target yakit-full-web.service
Wants=network-online.target
[Service]
Type=simple
User=yakview
Group=yakview
WorkingDirectory=/opt/yakit-mobile-native
Environment=HOME=/var/lib/yakit-full
Environment=YAKIT_MOBILE_STATE=/var/lib/yakit-mobile
Environment=YAKIT_DESKTOP_STATE=/var/lib/yakit-full
ExecStart=/opt/yakit-full/venv/bin/python /opt/yakit-mobile-native/app.py
Restart=on-failure
RestartSec=4
UMask=0077
NoNewPrivileges=true
PrivateTmp=true
PrivateDevices=true
ProtectSystem=strict
ProtectHome=true
ReadWritePaths=/var/lib/yakit-mobile
RestrictAddressFamilies=AF_UNIX AF_INET AF_INET6
[Install]
WantedBy=multi-user.target
SERVICE
printf '%s\n' '[3/4] Starting only yakit-mobile-native.service...'
systemctl daemon-reload
systemctl enable --now yakit-mobile-native >/dev/null
systemctl restart yakit-mobile-native
sleep 3
printf '%s\n' '[4/4] Checking new service and preserving existing systems...'
systemctl is-active --quiet yakit-mobile-native || { journalctl -u yakit-mobile-native -n 25 --no-pager; exit 1; }
curl -fsS --max-time 5 -H 'Host: kitty.cedarmondtv.site' http://127.0.0.1:6090/healthz
echo
printf '%s\n' 'SUCCESS: Mobile-first Yakit Workbench on localhost:6090.'
printf '%s\n' 'No PataPesa services or full desktop components changed.'
printf '%s\n' 'After confirming the healthz result, change ONLY Kitty tunnel Service URL to 127.0.0.1:6090 (HTTP).'